function nodeResizeReducer(
  resize: NodeResize,
  action: NodeResizeAction,
): NodeResize {
  switch (action.type) {
    case "grab":
      return NodeResize.grab(action.held);
    case "track":
      return NodeResize.withSnapGuides(resize, action.guides);
    case "release":
      return NodeResize.release(resize);
    case "cancel":
    case "consume_click":
      // 掴んだものを手放して最初の状態へ戻す（取り消しも、click を飲み込んだあとも同じ）。
      return NodeResize.create();
  }
}

/**
 * 軸に沿って伸び縮みする辺の組（幅なら左右の辺、高さなら上下の辺）。
 *
 * `unit/side` は辺の組を軸とは別の語彙にしているので、対応はこのモジュールの都合として持つ。
 */
const SidePairByAxis = {
  width: SidePairs.Horizontal,
  height: SidePairs.Vertical,
} as const satisfies Readonly<Record<Axis, SidePair>>;

function withGrabbedEdgesAt(
  bounds: CanvasBounds,
  grabbed: GrabbedEnds,
  destinationOf: (
    edge: Readonly<{ axis: Axis; end: AxisEnd }>,
  ) => Option<number>,
): CanvasBounds {
  return Object.values(Axes).reduce(
    (moving, axis) =>
      Option.unwrapOr(
        Option.flatMap(grabbed[axis], (end) =>
          Option.map(destinationOf({ axis, end }), (at) =>
            CanvasBounds.withEdgeAt(moving, { axis, end }, at),
          ),
        ),
        moving,
      ),
    bounds,
  );
}

const trackPointer = (event: ReactPointerEvent<HTMLElement>) => {
  const tracked = NodeResize.trackedAt(
    CommandKey.isHeld(event) ? NodeResize.withoutSnapTargets(resize) : resize,
    CanvasPointer.offsetOf(event),
    params.view,
  );
  if (!Option.isSome(tracked)) {
    return;
  }
  const continuity = hasResized.current
    ? EditContinuities.Continued
    : EditContinuities.Separate;
  hasResized.current = true;
  params.onResize(tracked.value.edit, continuity);
  dispatch({ type: "track", guides: tracked.value.guides });
};

function GuideLineAlong({
  guides,
  pair,
}: Readonly<{ guides: SnapGuides; pair: SidePair }>): ReactElement | null {
  const guide = guides[pair];
  return Option.isSome(guide) ? (
    <GuideLine bounds={guide.value.guideLine} />
  ) : null;
}

/**
 * 1 つの軸のスマートガイド。ガイド線と、揃え先から離れていれば隙間の短い線と数値。
 *
 * @returns ガイド線と隙間の表示。その軸に揃った線が無ければ線も隙間も出ない（`toGapReadout` も
 *   `none` を返す）
 */
function Guide({
  guides,
  pair,
  view,
}: Readonly<{
  guides: SnapGuides;
  pair: SidePair;
  view: CanvasView;
}>): ReactElement {
  const readout = SideSnap.toGapReadout(guides, pair, view);
  return (
    <>
      <GuideLineAlong guides={guides} pair={pair} />
      {Option.isSome(readout) ? <GapLine readout={readout.value} /> : null}
    </>
  );
}

/**
 * 揃った線に引くガイド線だけを出す（docs/06-ui.md「リサイズハンドル」の辺のスナップ）。見た目は
 * `SnapGuideOverlay` のガイド線と同じで、揃え先との隙間の数値はまだ出さない。
 */
export function GuideLineOverlay({ guides }: Readonly<{ guides: SnapGuides }>) {
  return (
    <>
      <GuideLineAlong guides={guides} pair={SidePairs.Horizontal} />
      <GuideLineAlong guides={guides} pair={SidePairs.Vertical} />
    </>
  );
}

toEdgeSnapped(
  snap: SideSnap,
  grabbed: GrabbedEnds,
  moved: Offset,
): SideSnapped {
  const destination = withGrabbedEdgesAt(snap.moving, grabbed, (edge) =>
    Option.some(
      CanvasBounds.edgeAt(snap.moving, edge.axis, edge.end) +
        Offset.along(moved, edge.axis),
    ),
  );
  const lineAlong = (axis: Axis): Option<SnappedLine> =>
    Option.flatMap(grabbed[axis], (end) =>
      nearestEdge({ ...snap, moving: destination }, { axis, end }),
    );
  const lines = {
    width: lineAlong(Axes.Width),
    height: lineAlong(Axes.Height),
  };
  const snapped = withGrabbedEdgesAt(destination, grabbed, (edge) =>
    Option.map(lines[edge.axis], (line) => line.stationaryLine),
  );
  const guideAlong = (axis: Axis): Option<SnapGuide> =>
    Option.flatMap(lines[axis], (line) => guideOf(line, snapped));
  return {
    offset: { x: shiftOf(lines.width), y: shiftOf(lines.height) },
    guides: {
      [SidePairByAxis.width]: guideAlong(Axes.Width),
      [SidePairByAxis.height]: guideAlong(Axes.Height),
    },
  };
},

map<T, U>(option: Option<T>, fn: (value: T) => U): Option<NonNullable<U>> {
  return option.some ? Option.fromNullable(fn(option.value)) : none;
},

/**
 * 値があれば、不在になりうる次の処理へ渡す。
 *
 * @param option 渡す元
 * @param fn 値があるときだけ呼ぶ次の処理
 * @returns `option` が `none` なら `none`。値があれば `fn` の戻り値そのもの
 */
flatMap<T, U>(option: Option<T>, fn: (value: T) => Option<U>): Option<U> {
  return option.some ? fn(option.value) : none;
},

test("右辺を動かすと、左辺は留まり幅が変わる", () => {
  expect(
    CanvasBounds.withEdgeAt(Bounds, { axis: "width", end: "end" }, 150),
  ).toEqual({ left: 10, top: 20, width: 140, height: 40 });
});

test("左辺を動かすと、右辺は留まり左辺の位置と幅が変わる", () => {
  expect(
    CanvasBounds.withEdgeAt(Bounds, { axis: "width", end: "start" }, 30),
  ).toEqual({ left: 30, top: 20, width: 80, height: 40 });
});

test("下辺を動かすと、上辺は留まり高さが変わる", () => {
  expect(
    CanvasBounds.withEdgeAt(Bounds, { axis: "height", end: "end" }, 90),
  ).toEqual({ left: 10, top: 20, width: 100, height: 70 });
});

test("上辺を動かすと、下辺は留まり上辺の位置と高さが変わる", () => {
  expect(
    CanvasBounds.withEdgeAt(Bounds, { axis: "height", end: "start" }, 5),
  ).toEqual({ left: 10, top: 5, width: 100, height: 55 });
});

test("辺が反対の辺を越えると、左右を入れ替えず幅が負になる", () => {
  expect(
    CanvasBounds.withEdgeAt(Bounds, { axis: "width", end: "end" }, 0),
  ).toEqual({ left: 10, top: 20, width: -10, height: 40 });
});

test("掴んだ右辺が揃え先の右辺に揃うと、揃え先の右辺に縦のガイド線が出る", () => {
  const snapped = SideSnap.toEdgeSnapped(
    SideSnap.create(Moving, [RightAt144]),
    GrabbedRight,
    Offset.Origin,
  );

  expect(
    Option.map(snapped.guides.horizontal, (guide) => ({
      left: guide.guideLine.left,
      width: guide.guideLine.width,
    })),
  ).toEqual(Option.some({ left: 143, width: 2 }));
});

test("掴んでいない上下の辺が揃え先の上辺の近くにあっても、横のガイド線は出ない", () => {
  // 上辺は 103 で Moving の上辺 100 から 3。右辺 144 には揃うので縦の線は出る
  const topAt103: CanvasBounds = { left: 44, top: 103, width: 100, height: 20 };

  const snapped = SideSnap.toEdgeSnapped(
    SideSnap.create(Moving, [topAt103]),
    GrabbedRight,
    Offset.Origin,
  );

  expect(snapped.guides.vertical).toEqual(Option.none);
});

test("ガイド線は伸ばしたあとのものと揃え先の両方をまたぐ長さで出る", () => {
  const snapped = SideSnap.toEdgeSnapped(
    SideSnap.create(Moving, [RightAt144]),
    GrabbedRight,
    Offset.Origin,
  );

  // 伸ばしたものの上辺 100 から、揃え先の下辺 320 まで
  expect(verticalSpanOfVerticalLine(snapped)).toEqual(
    Option.some({ top: 100, height: 220 }),
  );
});

test("掴んだ辺が既に揃え先の辺に重なっていて寄せ量が 0 でも、ガイド線は出る", () => {
  const rightAt140: CanvasBounds = {
    left: 40,
    top: 300,
    width: 100,
    height: 20,
  };

  const snapped = SideSnap.toEdgeSnapped(
    SideSnap.create(Moving, [rightAt140]),
    GrabbedRight,
    Offset.Origin,
  );

  expect(Option.isSome(snapped.guides.horizontal)).toBe(true);
});

test("掴んだ辺が揃うとみなす距離より離れていれば、ガイド線は出ない", () => {
  const rightAt147: CanvasBounds = {
    left: 47,
    top: 300,
    width: 100,
    height: 20,
  };

  const snapped = SideSnap.toEdgeSnapped(
    SideSnap.create(Moving, [rightAt147]),
    GrabbedRight,
    Offset.Origin,
  );

  expect(snapped.guides.horizontal).toEqual(Option.none);
});

test("掴んでいない左辺が揃え先の辺の近くにあっても、ガイド線は出ない", () => {
  // 左辺どうしは 3 離れているだけ。右辺は 303 で遠い
  const leftAt103: CanvasBounds = {
    left: 103,
    top: 300,
    width: 200,
    height: 20,
  };

  const snapped = SideSnap.toEdgeSnapped(
    SideSnap.create(Moving, [leftAt103]),
    GrabbedRight,
    Offset.Origin,
  );

  expect(snapped.guides.horizontal).toEqual(Option.none);
});

test("掴んだ辺が揃え先の中心線の近くにあっても、ガイド線は出ない", () => {
  // 左右の中心線は 138 で右辺 140 から 2 だけ。辺は 123 / 153 でどちらも届かない
  const midlineAt138: CanvasBounds = {
    left: 123,
    top: 300,
    width: 30,
    height: 20,
  };

  const snapped = SideSnap.toEdgeSnapped(
    SideSnap.create(Moving, [midlineAt138]),
    GrabbedRight,
    Offset.Origin,
  );

  expect(snapped.guides.horizontal).toEqual(Option.none);
});

test("右下の角で幅と高さの両方が揃うと、縦のガイド線は高さを寄せたあとの下辺までまたぐ", () => {
  // 右辺 144 の揃え先は上 0・下 20 にあり、下辺 124 の揃え先は左右 600 / 640 で遠い
  const rightAt144Above: CanvasBounds = {
    left: 44,
    top: 0,
    width: 100,
    height: 20,
  };
  const bottomAt124: CanvasBounds = {
    left: 600,
    top: 24,
    width: 40,
    height: 100,
  };

  const snapped = SideSnap.toEdgeSnapped(
    SideSnap.create(Moving, [rightAt144Above, bottomAt124]),
    GrabbedBottomRight,
    Offset.Origin,
  );

  // 揃え先の上辺 0 から、寄せたあとの下辺 124 まで（寄せる前の下辺なら 120）
  expect(verticalSpanOfVerticalLine(snapped)).toEqual(
    Option.some({ top: 0, height: 124 }),
  );
});

test("掴んだ下辺が揃え先の下辺に揃うと、揃え先の下辺に横のガイド線が出る", () => {
  const snapped = SideSnap.toEdgeSnapped(
    SideSnap.create(Moving, [BottomAt124]),
    GrabbedBottom,
    Offset.Origin,
  );

  expect(
    Option.map(snapped.guides.vertical, (guide) => ({
      top: guide.guideLine.top,
      height: guide.guideLine.height,
    })),
  ).toEqual(Option.some({ top: 123, height: 2 }));
});

test("右下の角で幅と高さの両方が揃うと、横のガイド線は幅を寄せたあとの右辺までまたぐ", () => {
  // 下辺 124 の揃え先は左 0・右 20 にあり、右辺 144 の揃え先は上下 300 / 320 で遠い
  const bottomAt124Left: CanvasBounds = {
    left: 0,
    top: 24,
    width: 20,
    height: 100,
  };

  const snapped = SideSnap.toEdgeSnapped(
    SideSnap.create(Moving, [RightAt144, bottomAt124Left]),
    GrabbedBottomRight,
    Offset.Origin,
  );

  // 揃え先の左辺 0 から、寄せたあとの右辺 144 まで（寄せる前の右辺なら 140）
  expect(horizontalSpanOfHorizontalLine(snapped)).toEqual(
    Option.some({ left: 0, width: 144 }),
  );
});

test("右下の角を反対の辺を越えた先まで運んで幅と高さの両方が揃うと、どちらのガイド線も越えた先の辺までまたぐ", () => {
  // 右辺 140 → 80・下辺 120 → 90 まで運び、左辺 100・上辺 100 を越える
  const rightAt78: CanvasBounds = { left: 38, top: 200, width: 40, height: 20 };
  const bottomAt88: CanvasBounds = {
    left: 200,
    top: 48,
    width: 20,
    height: 40,
  };

  const snapped = SideSnap.toEdgeSnapped(
    SideSnap.create(Moving, [rightAt78, bottomAt88]),
    GrabbedBottomRight,
    { x: -60, y: -30 },
  );

  // 縦の線は越えた先の下辺 88 から、横の線は越えた先の右辺 78 から（0 で止めた矩形なら 100 から）
  expect({
    verticalLineTop: Option.map(
      verticalSpanOfVerticalLine(snapped),
      (span) => span.top,
    ),
    horizontalLineLeft: Option.map(
      horizontalSpanOfHorizontalLine(snapped),
      (span) => span.left,
    ),
  }).toEqual({
    verticalLineTop: Option.some(88),
    horizontalLineLeft: Option.some(78),
  });
});

test("掴んだ辺が揃うとみなす距離ちょうどにあれば寄せる", () => {
  const stationary: CanvasBounds = {
    left: 46,
    top: 300,
    width: 100,
    height: 20,
  };

  expect(
    SideSnap.toEdgeSnapped(
      SideSnap.create(Moving, [stationary]),
      GrabbedRight,
      Offset.Origin,
    ).offset.x,
  ).toBe(SideSnap.ThresholdPx);
});

test("掴んだ辺が揃うとみなす距離より 1 でも離れていれば寄せない", () => {
  const stationary: CanvasBounds = {
    left: 47,
    top: 300,
    width: 100,
    height: 20,
  };

  expect(
    SideSnap.toEdgeSnapped(
      SideSnap.create(Moving, [stationary]),
      GrabbedRight,
      Offset.Origin,
    ).offset.x,
  ).toBe(0);
});

test("右辺を掴んで揃え先の右辺の近くまで運ぶと、揃え先の右辺に縦のガイド線が出る", () => {
  const resize = grabbedWithSnap({ x: 1, y: 0.5 }, { x: 300, y: 100 }, [
    RightAt340,
  ]);

  const tracked = NodeResize.trackedAt(resize, { x: 337, y: 100 }, setupView());

  expect(
    Option.flatMap(tracked, ({ guides }) =>
      Option.map(guides.horizontal, (guide) => ({
        left: guide.guideLine.left,
        width: guide.guideLine.width,
      })),
    ),
  ).toEqual(Option.some({ left: 339, width: 2 }));
});

test("左辺を掴んで揃え先の左辺の近くまで運ぶと、揃え先の左辺に縦のガイド線が出る", () => {
  // 左辺が 130 にある揃え先（右辺は 630 で遠い）
  const leftAt130: CanvasBounds = {
    left: 130,
    top: 400,
    width: 500,
    height: 20,
  };
  const resize = grabbedWithSnap({ x: 0, y: 0.5 }, { x: 100, y: 100 }, [
    leftAt130,
  ]);

  const tracked = NodeResize.trackedAt(resize, { x: 133, y: 100 }, setupView());

  expect(
    Option.flatMap(tracked, ({ guides }) =>
      Option.map(guides.horizontal, (guide) => ({
        left: guide.guideLine.left,
        width: guide.guideLine.width,
      })),
    ),
  ).toEqual(Option.some({ left: 129, width: 2 }));
});

test("右辺を掴んだままポインタが縦にもずれても、ガイド線は描かれている上辺・下辺と揃え先をまたぐ", () => {
  const resize = grabbedWithSnap({ x: 1, y: 0.5 }, { x: 300, y: 100 }, [
    RightAt340,
  ]);

  // 縦に 30 ずれても幅しか変わらないので、上辺 50 から揃え先の下辺 420 まで
  const tracked = NodeResize.trackedAt(resize, { x: 337, y: 130 }, setupView());

  expect(
    Option.flatMap(tracked, ({ guides }) =>
      Option.map(guides.horizontal, (guide) => ({
        top: guide.guideLine.top,
        height: guide.guideLine.height,
      })),
    ),
  ).toEqual(Option.some({ top: 50, height: 370 }));
});

test("下辺を掴んだままポインタが横にもずれても、ガイド線は描かれている左辺・右辺と揃え先をまたぐ", () => {
  // 下辺が 180 にある揃え先（左右の辺は 600 / 640 で遠い）
  const bottomAt180: CanvasBounds = {
    left: 600,
    top: 80,
    width: 40,
    height: 100,
  };
  const resize = grabbedWithSnap({ x: 0.5, y: 1 }, { x: 200, y: 150 }, [
    bottomAt180,
  ]);

  // 横に 30 ずれても高さしか変わらないので、左辺 100 から揃え先の右辺 640 まで
  const tracked = NodeResize.trackedAt(resize, { x: 230, y: 177 }, setupView());

  expect(
    Option.flatMap(tracked, ({ guides }) =>
      Option.map(guides.vertical, (guide) => ({
        left: guide.guideLine.left,
        width: guide.guideLine.width,
      })),
    ),
  ).toEqual(Option.some({ left: 100, width: 540 }));
});

test("揃え先の辺の近くまで運んでいなければ、ガイド線は出ない", () => {
  const resize = grabbedWithSnap({ x: 1, y: 0.5 }, { x: 300, y: 100 }, [
    RightAt340,
  ]);

  // 右辺は 320 で、揃え先の右辺 340 から 20 離れている
  const tracked = NodeResize.trackedAt(resize, { x: 320, y: 100 }, setupView());

  expect(Option.map(tracked, ({ guides }) => guides)).toEqual(
    Option.some(SideSnap.NoGuides),
  );
});

test("辺のスナップの組を載せていない掴みでは、揃え先の近くでもガイド線は出ない", () => {
  const resize = grabbedAt(
    setupResizable(),
    { x: 1, y: 0.5 },
    { x: 300, y: 100 },
  );

  const tracked = NodeResize.trackedAt(resize, { x: 337, y: 100 }, setupView());

  expect(Option.map(tracked, ({ guides }) => guides)).toEqual(
    Option.some(SideSnap.NoGuides),
  );
});

test("揃え先を外した掴みでは、揃え先の近くまで運んでもガイド線は出ない", () => {
  const resize = NodeResize.withoutSnapTargets(
    grabbedWithSnap({ x: 1, y: 0.5 }, { x: 300, y: 100 }, [RightAt340]),
  );

  const tracked = NodeResize.trackedAt(resize, { x: 337, y: 100 }, setupView());

  expect(Option.map(tracked, ({ guides }) => guides)).toEqual(
    Option.some(SideSnap.NoGuides),
  );
});

test("右下の角を掴んで幅と高さの両方が揃うと、縦と横のガイド線が 1 本ずつ出る", () => {
  // 下辺が 180 にある揃え先（左右の辺は 600 / 640 で遠い）
  const bottomAt180: CanvasBounds = {
    left: 600,
    top: 80,
    width: 40,
    height: 100,
  };
  const resize = grabbedWithSnap({ x: 1, y: 1 }, { x: 300, y: 150 }, [
    RightAt340,
    bottomAt180,
  ]);

  const tracked = NodeResize.trackedAt(resize, { x: 337, y: 176 }, setupView());

  expect(
    Option.map(tracked, ({ guides }) => ({
      horizontal: Option.isSome(guides.horizontal),
      vertical: Option.isSome(guides.vertical),
    })),
  ).toEqual(Option.some({ horizontal: true, vertical: true }));
});

test("掴んでいる状態に載せた揃った線が、今出すガイド線として返る", () => {
  const resize = grabbedWithSnap({ x: 1, y: 0.5 }, { x: 300, y: 100 }, [
    RightAt340,
  ]);
  const tracked = Option.unwrap(
    NodeResize.trackedAt(resize, { x: 337, y: 100 }, setupView()),
  );

  expect(
    NodeResize.snapGuides(NodeResize.withSnapGuides(resize, tracked.guides)),
  ).toEqual(tracked.guides);
});

test("右辺を掴んで揃え先の右辺の近くまで運ぶと、右辺が揃う幅の編集になる", () => {
  const resize = grabbedWithSnap({ x: 1, y: 0.5 }, { x: 300, y: 100 }, [
    RightAt340,
  ]);

  // 寄せが無ければ右辺は 337 で幅 237
  expect(resizeEditAt(resize, { x: 337, y: 100 }, setupView())).toEqual(
    Option.some(ResizeEdit.create([{ axis: "width", length: 240 }])),
  );
});

test("揃った線の数だけガイド線が出る", () => {
  render(
    <GuideLineOverlay
      guides={{
        horizontal: Option.some({
          guideLine: VerticalLine,
          gapLine: Option.none,
        }),
        vertical: Option.some({
          guideLine: HorizontalLine,
          gapLine: Option.none,
        }),
      }}
    />,
  );

  expect(screen.queryAllByTestId("snap-guide")).toHaveLength(2);
});

test("ガイド線は渡された矩形の位置と長さで出る", () => {
  render(
    <GuideLineOverlay
      guides={{
        horizontal: Option.some({
          guideLine: VerticalLine,
          gapLine: Option.none,
        }),
        vertical: Option.none,
      }}
    />,
  );

  expect(screen.getByTestId("snap-guide").getAttribute("style")).toContain(
    "left: 249px; top: 150px; width: 2px; height: 90px",
  );
});

